export const arrivalCopy=language=>copy[language]||copy.hr;
export const ARRIVAL_SOURCES={car:'https://www.hak.hr/info/stanje-na-cestama/',bus:'https://www.kolodvor.hr/',plane:'https://platanus.hr/hr/cesto-postavljana-pitanja/',boat:'https://www.jadrolinija.hr/en/travel/ploce_%25E2%2580%2593_trpanj__peljesac'};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function arrivalLinks(site){const address=site.address||'Luka Dubrava 28, 20248 Dubrava, Pelješac, Hrvatska';return {address,map:site.mapsUrl||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address),directions:'https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(address),embed:site.mapEmbed||'https://www.google.com/maps?q='+encodeURIComponent(address)+'&output=embed'}}
const icons={car:'<path d="m5 8 2-5h10l2 5M3 8h18v11H3V8Zm3 11v3m12-3v3M6 12h.01M18 12h.01"/>',bus:'<rect x="4" y="2" width="16" height="18" rx="3"/><path d="M4 11h16M8 20v2m8-2v2M8 16h.01m8 0h.01M8 5h8"/>',plane:'<path d="m2 10 8-1 1-7h2l1 7 8 1v2l-8 2-1 6h3v2H8v-2h3l-1-6-8-2v-2Z"/>',boat:'<path d="M3 15 12 12l9 3-3 6H6l-3-6Zm4-1V5h10v9M10 5V2h4v3M2 22c2-2 4 2 6 0s4 2 6 0 4 2 8 0"/>'};
export function arrivalContent(site,language='hr'){
 const c=arrivalCopy(language),links=arrivalLinks(site);
 return `<section class="section"><div class="wrap arrival-location"><div><span class="eyebrow">${esc(c.location)}</span><h2>${esc(site.name)}</h2><address>${esc(links.address)}</address><div class="actions"><a class="btn" href="${esc(links.directions)}" target="_blank" rel="noopener noreferrer">${esc(c.directions)} ↗</a><a class="text-link" href="${esc(links.map)}" target="_blank" rel="noopener noreferrer">${esc(c.map)} ↗</a></div></div>${consentMapMarkup(links.embed,c.location,language)}</div></section><section class="section cream"><div class="wrap"><h2>${esc(c.ways)}</h2><div class="arrival-grid">${Object.entries(ARRIVAL_SOURCES).map(([key,source])=>`<article class="arrival-card"><h3><svg class="amenity-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[key]}</svg><span>${esc(c[key])}</span></h3><p>${esc(c[key+'Text'])}</p><a class="text-link" href="${esc(source)}" target="_blank" rel="noopener noreferrer">${esc(c[key+'Link'])} ↗</a></article>`).join('')}</div><p class="section-note">${esc(c.note)}</p></div></section><section class="section"><div class="wrap arrival-parking"><div><h2>${esc(c.parking)}</h2><p>${esc(c.parkingText)}</p>${site.checkIn?`<p><strong>${esc(c.checkIn)}:</strong> ${esc(site.checkIn)}</p>`:''}</div><a class="btn" href="/kontakt/${language==='hr'?'':'?lang='+language}">${esc(c.contact)} ↗</a></div></section>`;
}
